import six
from abc import ABCMeta, abstractmethod


@six.add_metaclass(ABCMeta)
class Recorder(object):

    @abstractmethod
    def add(self, data):
        """pass"""

    def start(self):
        pass

    def stop(self):
        pass

    def reset(self):
        pass


class DictRecorder(Recorder):

    def __init__(self, output):
        self._data_dict = output

    def reset(self):
        self._data_dict.clear()

    def add(self, data):
        key_cell = data.get_key_cell()
        item = {'connection_id': data.connection.value,
                'interval': (data.interval.interval_start, data.interval.interval_end),
                'throughput': key_cell.value,
                'unit': key_cell.unit}
        if data.connection.value in self._data_dict:
            self._data_dict[data.connection.value].append(item)
        else:
            self._data_dict[data.connection.value] = [item]


class DoNothingRecorder(Recorder):
    def add(self, data):
        pass
